const _green = Color(0xFF0B7A53), _greenDark = Color(0xFF075C3E), _mint = Color(0xFFEAF7F1), _bg = Color(0xFFF5F8F6), _ink = Color(0xFF17221C), _muted = Color(0xFF6D776F), _line = Color(0xFFE1E9E4), _orange = Color(0xFFE36A2D);
const _apiBase = String.fromEnvironment('AASPASS_API_BASE_URL', defaultValue: 'http://10.0.2.2:4100/api/v1');
void main(){WidgetsFlutterBinding.ensureInitialized();runApp(const AasPassVendorApp());}

class VendorApi {
  Future<Map<String,String>> _headers() async { final p=await SharedPreferences.getInstance(); final t=p.getString('aaspass_vendor_token'); return {'content-type':'application/json','accept':'application/json',if(t!=null&&t.isNotEmpty)'Authorization':'Bearer $t'}; }
  Future<dynamic> get(String path) async { final r=await http.get(Uri.parse('$_apiBase$path'),headers:await _headers()).timeout(const Duration(seconds:12)); return _handle(r); }
  Future<dynamic> post(String path,Map<String,dynamic> body) async { final r=await http.post(Uri.parse('$_apiBase$path'),headers:await _headers(),body:jsonEncode(body)).timeout(const Duration(seconds:12)); return _handle(r); }
  Future<dynamic> patch(String path,Map<String,dynamic> body) async { final r=await http.patch(Uri.parse('$_apiBase$path'),headers:await _headers(),body:jsonEncode(body)).timeout(const Duration(seconds:12)); return _handle(r); }
  dynamic _handle(http.Response r){if(r.statusCode>=400)throw Exception(r.body);return r.body.isEmpty?<String,dynamic>{}:jsonDecode(r.body);}
  Future<Map<String,dynamic>> me() async=>Map<String,dynamic>.from((await get('/vendor/me'))['vendor']??{});
  Future<Map<String,dynamic>> dashboard() async=>Map<String,dynamic>.from(await get('/vendor/dashboard'));
  Future<Map<String,dynamic>> analytics({int days=30}) async=>Map<String,dynamic>.from(await get('/vendor/analytics?days=$days'));
  Future<List<Map<String,dynamic>>> products() async=>((await get('/vendor/products'))['products'] as List).map((e)=>Map<String,dynamic>.from(e)).toList();
  Future<List<Map<String,dynamic>>> orders() async=>((await get('/vendor/orders'))['orders'] as List).map((e)=>Map<String,dynamic>.from(e)).toList();
  Future<void> storeStatus(bool isOpen) async{await post('/vendor/status',{'isOpen':isOpen});}
  Future<void> location(Position p) async{await post('/vendor/location',{'latitude':p.latitude,'longitude':p.longitude});}
  Future<void> orderStatus(String id,String status) async{await post('/vendor/orders/$id/status',{'status':status});}
  Future<void> updateProduct(String id,Map<String,dynamic> body) async{await patch('/vendor/products/$id',body);}
  Future<void> createProduct(Map<String,dynamic> body) async{await post('/vendor/products',body);}
}

