class VendorGate extends StatefulWidget{const VendorGate({super.key});@override State<VendorGate> createState()=>_VendorGateState();}
class _VendorGateState extends State<VendorGate>{bool logged=false,loading=true,busy=false;String phone='',otp='',message='';final api=VendorApi();@override void initState(){super.initState();_load();}Future<void> _load()async{final p=await SharedPreferences.getInstance();if(mounted)setState((){logged=(p.getString('aaspass_vendor_token')??'').isNotEmpty;loading=false;});}
Future<void> _login()async{if(otp!='270303'){setState(()=>message='Development authentication requires OTP 270303.');return;}setState((){busy=true;message='';});try{final n=phone.replaceAll(RegExp(r'\D'),'');final r=await http.post(Uri.parse('$_apiBase/auth/dev/login'),headers:{'content-type':'application/json'},body:jsonEncode({'phone':'+91$n','otp':otp,'role':'VENDOR_OWNER','name':'AasPass Vendor'})).timeout(const Duration(seconds:10));if(r.statusCode>=400)throw Exception(r.body);final d=jsonDecode(r.body);final p=await SharedPreferences.getInstance();await p.setString('aaspass_vendor_token','${d['accessToken']}');if(mounted)setState((){busy=false;logged=true;});}catch(e){if(mounted)setState((){busy=false;message='AasPass server connection failed. $e';});}}
@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(logged)return const VendorShell();return Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(20),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:500),child:Column(children:[SizedBox(width:78,height:78,child:Padding(padding:EdgeInsets.all(14),child:Image(image:AssetImage('assets/branding/AasPass-icon.png')))),SizedBox(height:18),Text('AasPass Vendor',style:TextStyle(color:_muted,fontWeight:FontWeight.w700)),SizedBox(height:6),Text('Run your local store from one calm workspace.',textAlign:TextAlign.center,style:TextStyle(fontSize:28,fontWeight:FontWeight.w900,color:_ink)),SizedBox(height:22),Card(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(24)),child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Sign in',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:14),TextField(keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Registered mobile',prefixText:'+91 '),onChanged:(v)=>phone=v),const SizedBox(height:12),TextField(keyboardType:TextInputType.number,obscureText:true,maxLength:6,decoration:const InputDecoration(labelText:'OTP',counterText:''),onChanged:(v)=>otp=v),if(message.isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Text(message,style:const TextStyle(color:_orange,fontSize:11))),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:_login,child:Text(busy?'Signing in…':'Continue'))),const SizedBox(height:10),const Text('Production authentication must be connected to the shared AasPass identity provider before release.',style:TextStyle(fontSize:10,color:_muted))])))]))))));}}

class VendorShell extends StatefulWidget{const VendorShell({super.key});@override State<VendorShell> createState()=>_VendorShellState();}
class _VendorShellState extends State<VendorShell>{int index=0;bool loading=true;String? error;Map<String,dynamic> me={},dashboard={},analytics={};List<Map<String,dynamic>> orders=[],products=[];Position? pos;bool locationBusy=false,open=false;final api=VendorApi();@override void initState(){super.initState();_load();}
Future<void> _load()async{setState(()=>loading=true);try{final results=await Future.wait([api.me(),api.dashboard(),api.orders(),api.products(),api.analytics()]);me=Map<String,dynamic>.from(results[0] as Map);dashboard=Map<String,dynamic>.from(results[1] as Map);orders=List<Map<String,dynamic>>.from(results[2] as List);products=List<Map<String,dynamic>>.from(results[3] as List);analytics=Map<String,dynamic>.from(results[4] as Map);open=me['is_open']==true;await _locate(silent:true);if(mounted)setState(()=>loading=false);}catch(e){if(mounted)setState((){loading=false;error='Could not connect to the AasPass vendor services. $e';});}}
Future<void> _locate({bool silent=false})async{if(locationBusy)return;setState(()=>locationBusy=true);try{if(!await Geolocator.isLocationServiceEnabled()){if(!silent)await Geolocator.openLocationSettings();return;}var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.deniedForever){if(!silent)await Geolocator.openAppSettings();return;}if(p==LocationPermission.denied)return;final current=await Geolocator.getCurrentPosition(locationSettings:const LocationSettings(accuracy:LocationAccuracy.high));pos=current;await api.location(current);}catch(e){if(!silent&&mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Location integration failed: $e')));}finally{if(mounted)setState(()=>locationBusy=false);}}
Future<void> _toggle()async{final next=!open;try{await api.storeStatus(next);if(mounted)setState(()=>open=next);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not update store status: $e')));}}
Future<void> _orderAction(Map<String,dynamic> o)async{final status='${o['status']}';final next=status=='PLACED'||status=='PAID'||status=='COD_CONFIRMED'?'VENDOR_ACCEPTED':status=='VENDOR_ACCEPTED'?'PREPARING':status=='PREPARING'?'READY_FOR_PICKUP':null;if(next==null)return;try{await api.orderStatus('${o['id']}',next);await _load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Order update failed: $e')));}}
Future<void> _saveProduct(Map<String,dynamic> p,bool available)async{try{await api.updateProduct('${p['id']}',{'name':'${p['name']}','unitLabel':'${p['unit_label']??'1 unit'}','priceRupees':((p['price_paise'] as num?)?.toDouble()??0)/100,'stockQty':available?((p['stock_qty'] as num?)?.toInt()??1):0,'imageUrl':(p['image_url'] as String?)?.isNotEmpty==true?p['image_url']:null,'isActive':available});await _load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Inventory update failed: $e')));}}
